from __future__ import annotations

from dataclasses import dataclass
from typing import Any, Callable

ProgressCb = Callable[[dict[str, Any]], None]
CueCb = Callable[[dict[str, Any]], None]
CancelCb = Callable[[], bool]
RegisterProcCb = Callable[[Any], None]


@dataclass
class Cue:
    start: float
    end: float
    text: str

    def to_dict(self) -> dict[str, Any]:
        return {"start": self.start, "end": self.end, "text": self.text}


def run_asr(
    *,
    media_path: str,
    language: str = "auto",
    asr_model: str = "sensevoice-small",
    vad_model: str = "fsmn-vad",
    vad_options: dict[str, Any] | None = None,
    device: str = "auto",
    beam_size: int | None = None,
    clip_timestamps: list[dict[str, float]] | None = None,
    force_no_vad: bool = False,
    initial_prompt: str | None = None,
    hotwords: str | None = None,
    on_progress: ProgressCb | None = None,
    on_cue: CueCb | None = None,
    should_cancel: CancelCb | None = None,
    register_subprocess: RegisterProcCb | None = None,
    include_words: bool = False,
    word_timestamps: bool | None = None,
    force_inprocess: bool = False,
) -> list[dict[str, Any]]:
    from ..paths import is_stub_mode

    if is_stub_mode():
        from .stub import stub_transcribe

        cues = stub_transcribe(media_path=media_path, language=language, on_progress=on_progress)
        if include_words:
            for cue in cues:
                if "words" not in cue:
                    text = str(cue.get("text") or "")
                    cue["words"] = (
                        [
                            {
                                "word": text,
                                "start": cue.get("start"),
                                "end": cue.get("end"),
                            }
                        ]
                        if text
                        else []
                    )
        if on_cue:
            for cue in cues:
                on_cue(cue)
        return cues

    backend = "sensevoice"
    if "whisper" in str(asr_model):
        backend = "whisper"

    if backend == "whisper":
        from .whisper_fw import whisper_transcribe

        return whisper_transcribe(
            media_path=media_path,
            language=language,
            asr_model=asr_model,
            device=device,
            beam_size=int(beam_size) if beam_size is not None else 5,
            vad_options=vad_options,
            clip_timestamps=clip_timestamps,
            force_no_vad=force_no_vad,
            initial_prompt=initial_prompt,
            hotwords=hotwords,
            on_progress=on_progress,
            on_cue=on_cue,
            should_cancel=should_cancel,
            include_words=include_words,
            word_timestamps=word_timestamps,
        )

    from .sensevoice import sensevoice_transcribe

    cues = sensevoice_transcribe(
        media_path=media_path,
        language=language,
        asr_model=asr_model,
        vad_model=vad_model,
        vad_options=vad_options,
        device=device,
        on_progress=on_progress,
        should_cancel=should_cancel,
        register_subprocess=register_subprocess,
        force_inprocess=force_inprocess,
    )
    if include_words:
        for cue in cues:
            if "words" not in cue:
                text = str(cue.get("text") or "")
                cue["words"] = (
                    [{"word": text, "start": cue.get("start"), "end": cue.get("end")}]
                    if text
                    else []
                )
    if on_cue:
        for cue in cues:
            on_cue(cue)
    return cues
